		codeProvider = waitForComponentProvider(typeof(CodeViewerProvider));

		listingPlugin = addPlugin(tool, typeof(DebuggerListingPlugin));
		listingProvider = waitForComponentProvider(typeof(DebuggerListingProvider));

		// TODO: If a task crashes, the test framework hangs.
